/**
 * Owner's rules applied on top of the source catalog. data/quick-order.json
 * keeps the source values (it is regenerated by extract-catalog.mjs); these
 * overrides are applied when the page loads the catalog.
 */
import { yenForWon } from "./price";
import type { Offer, Product, ProductGroup } from "./types";

/** Where purchase inquiries go: the cart's "결제하기" shows a notice that links here. */
export const INQUIRY_URL = "https://www.tiktok.com/@pokeshopkr";

/** The notice's second destination, shown as its own button under the TikTok one. */
export const INSTAGRAM_URL = "https://www.instagram.com/pokeparcelkr";

/** Official partner seller popyaa (TikTok), shown in its own section of the notice with the 5% code offer. */
export const PARTNER_URL = "https://www.tiktok.com/@popyaa3838";

/**
 * Groups whose products are shown as sold out ("포켓몬 스페셜", "포켓몬 벌크").
 * Matched on the product's own group, so their copies in "예약 주문 / HOT" are sold out too.
 */
export const SOLD_OUT_GROUPS = new Set(["pokemon-other", "pokemon-bulk"]);

/** An offer as the source renders it when out of stock: "품절", price kept, no quantity stepper. */
function soldOutOffer(offer: Offer): Offer {
  return { ...offer, stockState: "out", stockText: "품절", action: "unavailable", actionKind: "empty", max: 0 };
}

function applyProduct(product: Product): Product {
  if (!SOLD_OUT_GROUPS.has(product.group)) return product;
  return { ...product, stockTotal: 0, offers: product.offers.map(soldOutOffer) };
}

const SPOTLIGHT_NAME = "30th CELEBRATION 부스터 박스 한국판 포켓몬 카드";
const spotlightImg = (size: number) => `/images/products/30th-celebration-booster-box-korean-${size}.webp`;

/** Fixed shop price of the spotlight product (KRW). */
export const SPOTLIGHT_PRICE_WON = 70000;

/** The stock count is not known, so the card says "재고 있음" and one order takes at most this many. */
export const SPOTLIGHT_MAX_QTY = 99;

/** Large photo for the banner above the Pokemon list (Spotlight.tsx). */
export const SPOTLIGHT_BANNER_IMG = spotlightImg(640);

/**
 * Owner's spotlight product, not in the source catalog: the Korean 30th CELEBRATION
 * booster box with shrink, at the all-time low price. It is featured in the banner
 * above the Pokemon list and listed first in "예약 주문 / HOT" and "포켓몬 박스".
 */
export const SPOTLIGHT_PRODUCT: Product = {
  key: "30th-celebration-booster-box-korean",
  handle: "30th-celebration-booster-box-korean",
  rowClass: "sst-qo__row--single-offer sst-qo__row--spotlight",
  group: "pokemon-box",
  subgroup: "box",
  name: SPOTLIGHT_NAME,
  search: `30th celebration booster box korean pokemon card m6a ${SPOTLIGHT_NAME.toLowerCase()} 역대 할인가 슈링크 있음`,
  img: {
    src: spotlightImg(160),
    srcSet: `${spotlightImg(160)} 160w, ${spotlightImg(320)} 320w`,
    sizes: "(max-width: 749px) 36px, 130px",
    width: 160,
    height: 160,
    variant: "default",
    alt: SPOTLIGHT_NAME,
  },
  priceYen: yenForWon(SPOTLIGHT_PRICE_WON),
  stockTotal: SPOTLIGHT_MAX_QTY,
  hot: false,
  sale: false,
  flash: false,
  preorder: false,
  promoBadges: ["역대 할인가", "한국판"],
  offers: [
    {
      type: "sealed",
      classes: ["sst-qo__offer--sealed", "sst-qo__offer--single"],
      colSpan: 2,
      label: "슈링크 있음",
      stockText: "재고 있음",
      stockState: "in",
      action: "quantity",
      actionKind: "qty",
      priceState: "priced",
      priceYen: yenForWon(SPOTLIGHT_PRICE_WON),
      priceWon: SPOTLIGHT_PRICE_WON,
      max: SPOTLIGHT_MAX_QTY,
      // Outside the source catalog's variant ids (all below 101,000), so cart lines never collide.
      variantId: 900001,
      cartName: `${SPOTLIGHT_NAME} - 슈링크 있음`,
    },
  ],
};

/** A group's rows with the spotlight product first; "전체" hides the box copy, as for other HOT items. */
function withSpotlight(g: ProductGroup): Product[] {
  if (g.id === "pokemon-preorder") return [SPOTLIGHT_PRODUCT, ...g.rows];
  if (g.id === "pokemon-box") return [{ ...SPOTLIGHT_PRODUCT, dupOfFeatured: true }, ...g.rows];
  return g.rows;
}

export function applyShopRules(groups: ProductGroup[]): ProductGroup[] {
  return groups.map((g) => ({ ...g, rows: withSpotlight(g).map(applyProduct) }));
}
